import shutil
import re
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

SRC = "/root/data/workbook.xlsx"
DST = "/root/output/result.xlsx"

os.makedirs(os.path.dirname(DST), exist_ok=True)
shutil.copyfile(SRC, DST)

wb = load_workbook(DST, data_only=False)
ws_task = wb["Task"]
ws_data = wb["Data"]

# ----------------------
# Step 0: Inspect sheets
# ----------------------

def cell_str(v):
    return "" if v is None else str(v)

def print_grid(ws, min_row, max_row, min_col, max_col, title):
    print("\n" + title)
    cols = [get_column_letter(c) for c in range(min_col, max_col + 1)]
    print("row\t" + "\t".join(cols))
    for r in range(min_row, max_row + 1):
        vals = [cell_str(ws.cell(r, c).value) for c in range(min_col, max_col + 1)]
        print(str(r) + "\t" + "\t".join(vals))

print_grid(ws_task, 1, 55, 1, 12, "Task sheet structure: rows 1-55, cols A-L")

print("\nFocus: Task!D12:D31 (series codes)")
for r in range(12, 32):
    print(f"D{r}\t{cell_str(ws_task[f'D{r}'].value)}")

print("\nFocus: Task!H10:L10 (years)")
years_task_raw = []
for c in range(8, 13):
    addr = f"{get_column_letter(c)}10"
    v = ws_task.cell(10, c).value
    years_task_raw.append(v)
    print(f"{addr}\t{cell_str(v)}")

print_grid(ws_task, 12, 17, 8, 12, "Yellow range: Task!H12:L17")
print_grid(ws_task, 19, 24, 8, 12, "Yellow range: Task!H19:L24")
print_grid(ws_task, 26, 31, 8, 12, "Yellow range: Task!H26:L31")

print_grid(ws_task, 35, 50, 1, 12, "Task sheet: rows 35-50, cols A-L")

# Data sheet rows 18-40, all populated columns
max_col = ws_data.max_column
last_pop = 1
for r in range(18, 41):
    for c in range(1, max_col + 1):
        if ws_data.cell(r, c).value not in (None, ""):
            last_pop = max(last_pop, c)

print_grid(ws_data, 18, 40, 1, last_pop, f"Data sheet structure: rows 18-40, cols A-{get_column_letter(last_pop)}")

# Determine layout: years in a header row, series codes in a column, values matrix in rows 21:38

def normalize_year(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        iv = int(v)
        if abs(v - iv) < 1e-9 and 1900 <= iv <= 2100:
            return iv
    if isinstance(v, str):
        m = re.fullmatch(r"\s*(\d{4})\s*", v)
        if m:
            return int(m.group(1))
    return None

years_task = [normalize_year(v) for v in years_task_raw]

# Find year header row (try 18-25)
year_header_row = None
for r in range(18, 26):
    row_years = [normalize_year(ws_data.cell(r, c).value) for c in range(1, last_pop + 1)]
    if all(y in row_years for y in years_task if y is not None):
        year_header_row = r
        break

# Find series code column by matching Task series codes in Data rows 21:38
series_codes_task = []
for r in range(12, 32):
    v = ws_task.cell(r, 4).value
    if isinstance(v, str) and v.strip():
        series_codes_task.append(v.strip())

series_col = None
best_hits = -1
for c in range(1, last_pop + 1):
    hits = 0
    for r in range(21, 39):
        if ws_data.cell(r, c).value in series_codes_task:
            hits += 1
    if hits > best_hits:
        best_hits = hits
        series_col = c

print("\nData layout identification")
print("- Task years (normalized):", years_task)
print("- Found year header row in Data (18-25):", year_header_row)
print("- Found series code column in Data (rows 21-38):", f"{get_column_letter(series_col)} ({series_col})", "hits:", best_hits)

if year_header_row is None:
    raise SystemExit("ERROR: Could not find a Data year header row (18-25) containing Task years.")
if series_col is None or best_hits <= 0:
    raise SystemExit("ERROR: Could not find a Data series-code column matching Task series codes in Data rows 21:38.")

# Find the columns of each Task year on that header row
pos = {}
for y in years_task:
    for c in range(1, last_pop + 1):
        if normalize_year(ws_data.cell(year_header_row, c).value) == y:
            pos[y] = c
            break

start_col = min(pos.values())
end_col = max(pos.values())

start_col_letter = get_column_letter(start_col)
end_col_letter = get_column_letter(end_col)
series_col_letter = get_column_letter(series_col)

print("- Data is organized as: series codes down column", series_col_letter, "(rows 21-38), years across row", year_header_row)
print("- Using series range:", f"Data!${series_col_letter}$21:${series_col_letter}$38")
print("- Using year header range:", f"Data!${start_col_letter}${year_header_row}:${end_col_letter}${year_header_row}")
print("- Using values matrix:", f"Data!${start_col_letter}$21:${end_col_letter}$38")

# ----------------------------------------------
# Step 1: Populate lookup formulas in yellow cells
# ----------------------------------------------

def lookup_formula(task_row: int, task_col_letter: str) -> str:
    # INDEX(matrix, MATCH(series_code), MATCH(year))
    return (
        f"=INDEX(Data!${start_col_letter}$21:${end_col_letter}$38,"
        f"MATCH($D{task_row},Data!${series_col_letter}$21:${series_col_letter}$38,0),"
        f"MATCH({task_col_letter}$10,Data!${start_col_letter}${year_header_row}:${end_col_letter}${year_header_row},0))"
    )

blocks = [(12, 17), (19, 24), (26, 31)]
for r1, r2 in blocks:
    for r in range(r1, r2 + 1):
        for c in range(8, 13):  # H-L
            col_letter = get_column_letter(c)
            ws_task.cell(r, c).value = lookup_formula(r, col_letter)

# -------------------------------------------------
# Step 2a: H35:L40 Net capacity headroom (% points)
# -------------------------------------------------
for out_r in range(35, 41):
    avail_r = out_r - 23  # 35->12 ... 40->17
    occ_r = out_r - 16    # 35->19 ... 40->24
    staff_r = out_r - 9   # 35->26 ... 40->31
    for c in range(8, 13):
        col_letter = get_column_letter(c)
        ws_task.cell(out_r, c).value = f"=({col_letter}{avail_r}-{col_letter}{occ_r})/{col_letter}{staff_r}*100"

# -----------------------------------
# Step 2b: H42:L47 Summary statistics
# -----------------------------------
label_cols = [4, 3, 2, 1, 5]  # prefer D then C, etc.
labels = {}
for r in range(42, 48):
    lab = None
    for cc in label_cols:
        v = ws_task.cell(r, cc).value
        if isinstance(v, str) and v.strip():
            lab = v.strip()
            break
    labels[r] = lab

print("\nDetected summary statistic labels (rows 42-47):")
for r in range(42, 48):
    print(r, labels[r])

kind_by_row = {}
for r in range(42, 48):
    lab = (labels[r] or "").lower()
    kind = None
    if "min" in lab:
        kind = "min"
    elif "max" in lab:
        kind = "max"
    elif "median" in lab:
        kind = "median"
    elif "mean" in lab or "average" in lab:
        kind = "mean"
    elif "25" in lab or "0.25" in lab or "1st" in lab or "first" in lab:
        kind = "p25"
    elif "75" in lab or "0.75" in lab or "3rd" in lab or "third" in lab:
        kind = "p75"
    kind_by_row[r] = kind

# Fill any missing kinds in expected order
expected_order = ["min", "max", "median", "mean", "p25", "p75"]
used = {k for k in kind_by_row.values() if k}
remaining = [k for k in expected_order if k not in used]
for r in range(42, 48):
    if kind_by_row[r] is None:
        kind_by_row[r] = remaining.pop(0) if remaining else "mean"

print("\nSummary statistic kind mapping:")
for r in range(42, 48):
    print(r, labels[r], "->", kind_by_row[r])


def stat_formula(kind: str, col_letter: str) -> str:
    rng = f"{col_letter}35:{col_letter}40"
    if kind == "min":
        return f"=MIN({rng})"
    if kind == "max":
        return f"=MAX({rng})"
    if kind == "median":
        return f"=MEDIAN({rng})"
    if kind == "mean":
        return f"=AVERAGE({rng})"
    if kind == "p25":
        return f"=PERCENTILE({rng},0.25)"
    if kind == "p75":
        return f"=PERCENTILE({rng},0.75)"
    raise ValueError(kind)

for r in range(42, 48):
    kind = kind_by_row[r]
    for c in range(8, 13):
        col_letter = get_column_letter(c)
        ws_task.cell(r, c).value = stat_formula(kind, col_letter)

# -------------------------------
# Step 3: Weighted mean H50:L50
# -------------------------------
for c in range(8, 13):
    col_letter = get_column_letter(c)
    ws_task.cell(50, c).value = (
        f"=SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)"
        f"/SUM({col_letter}26:{col_letter}31)"
    )

# Step 4: Save
wb.save(DST)
wb.close()

# ----------------------
# Validation: reopen file
# ----------------------
wb2 = load_workbook(DST, data_only=False)
t = wb2["Task"]

print("\n=== Validation (should all be formulas starting with '=') ===")

def show(addr: str):
    v = t[addr].value
    print(f"{addr}\t{cell_str(v)}")

for addr in ["H12", "L17", "H19", "L24", "H26", "L31"]:
    show(addr)

for addr in ["H35", "L40"]:
    show(addr)

print("Stats formulas (H42:H47):")
for r in range(42, 48):
    show(f"H{r}")

show("H50")

wb2.close()
print("\nSaved workbook to:", DST)
